'use strict';
let portalArtSerial = 0;

// Original vector illustrations. Cutouts use masks so the paper below stays visible.
function renderPortalArtwork(motif, palette) {
  const id = 'portal-art-' + (++portalArtSerial);
  const { c1: red, c2: green, c3: gold, c4: blue, c5: rose } = palette;
  const paper = '#F4EBDD';
  function flower(x, y, radius, color, petals = 8) {
    let lobes = '', cuts = '';
    for (let n = 0; n < petals; n++) {
      const angle = n * 360 / petals;
      lobes += `<ellipse cx="0" cy="-28" rx="17" ry="25" transform="rotate(${angle})"/>`;
      cuts += `<path d="M0-44C-9-34-9-24 0-15C9-24 9-34 0-44Z" transform="rotate(${angle})"/>`;
    }
    const mask = id + '-flower-' + x + '-' + y;
    return `<g transform="translate(${x} ${y}) scale(${radius / 53})"><defs><mask id="${mask}" x="-60" y="-60" width="120" height="120" maskUnits="userSpaceOnUse"><g fill="white">${lobes}<circle r="26"/></g><g fill="black">${cuts}<circle r="7"/></g></mask></defs><g fill="${color}" mask="url(#${mask})"><rect x="-60" y="-60" width="120" height="120"/></g><circle r="12" fill="none" stroke="${gold}" stroke-width="1.4"/></g>`;
  }
  function branch(x, y, scale, flip = 1) {
    return `<g transform="translate(${x} ${y}) scale(${scale * flip} ${scale})" fill="${green}"><path d="M0 55Q-8 0 16-55L19-55Q0 5 4 55Z"/><path d="M2 17C-36 21-42-7-36-23C-13-20 3-2 2 17ZM6-9C35-3 48-22 44-39C20-40 7-28 6-9ZM12-30C-9-38-14-57-8-69C10-61 18-46 12-30Z"/><g fill="none" stroke="${paper}" stroke-width="1.2"><path d="M1 10-30-16M10-14 38-32M13-35-4-59"/></g></g>`;
  }
  let art = '';
  if (motif === 'mandala') {
    art = `<g class="art-back"><circle cx="150" cy="150" r="103" fill="${green}" opacity=".1"/><path d="M42 221H258M51 232H249" stroke="${gold}" stroke-width="1" opacity=".6"/>${branch(57,177,.7)}</g><g class="art-mid" transform="rotate(-13 152 145)"><path d="M78 60H229V219H78Z" fill="${red}"/><path d="M78 60 229 219M229 60 78 219" fill="none" stroke="${paper}" stroke-dasharray="3 4" opacity=".35"/><path d="M78 60H229L207 82H78Z" fill="${rose}"/>${flower(153,143,61,paper)}<path d="M87 69H219V209H87Z" fill="none" stroke="${gold}" stroke-width="1" opacity=".6"/></g><g class="art-front" transform="translate(199 209) rotate(-22)" fill="none" stroke="${blue}" stroke-linecap="round"><ellipse cx="-17" cy="22" rx="10" ry="14" stroke-width="5"/><ellipse cx="17" cy="22" rx="10" ry="14" stroke-width="5"/><path d="M-12 9 20-48Q28-40 15-16L-5 8M12 9-20-48Q-28-40-15-16L5 8" fill="${blue}" stroke-width="2"/><circle r="4" fill="${gold}" stroke-width="2"/></g><g fill="${red}" opacity=".65"><path d="m74 249 9-14 7 15Z"/><path d="m228 82 7-11 5 13Z"/></g>`;
  } else if (motif === 'flora') {
    art = `<g class="art-back"><circle cx="151" cy="143" r="90" fill="${gold}" opacity=".1"/><path d="M74 243Q170 212 224 67" stroke="${green}" stroke-width="5" fill="none"/>${branch(101,198,1.1,-1)}${branch(202,124,.85)}${branch(160,218,.65)}</g><g class="art-mid">${flower(131,128,70,red,9)}${flower(206,75,28,rose,7)}${flower(212,198,33,gold,6)}</g><g class="art-front" stroke="${paper}" stroke-width="1.5" fill="none"><path d="M80 158Q130 96 180 158M84 112Q132 149 176 110" opacity=".55"/></g><g fill="${rose}"><path d="M61 76Q41 53 59 43Q79 51 61 76ZM60 76Q79 54 88 69Q80 84 60 76Z"/><path d="M242 146Q224 123 241 115Q259 126 242 146Z"/></g><g fill="${gold}"><circle cx="70" cy="211" r="3"/><circle cx="238" cy="102" r="3"/><circle cx="184" cy="234" r="2"/></g>`;
  } else if (motif === 'phoenix') {
    let ribs = '';
    for (let n = 0; n <= 10; n++) { const angle = (-155 + n * 13) * Math.PI / 180; ribs += `<path d="M150 228L${150+116*Math.cos(angle)} ${228+116*Math.sin(angle)}"/>`; }
    art = `<g class="art-back"><circle cx="212" cy="87" r="25" fill="${gold}" opacity=".65"/><path d="M40 103Q92 58 145 99Q188 66 260 102" fill="none" stroke="${green}" stroke-width="2" opacity=".4"/></g><g class="art-mid"><path d="M40 161Q54 55 150 60Q246 55 260 161L150 238Z" fill="${red}"/><path d="M48 158Q65 69 150 71Q235 69 252 158" fill="none" stroke="${gold}" stroke-width="2"/><g fill="none" stroke="${paper}" stroke-width="1.2" opacity=".3">${ribs}</g><path d="M80 133Q101 149 127 129Q150 107 171 127Q192 145 218 125" stroke="${paper}" stroke-width="1.5" fill="none"/></g><g class="art-front"><path d="M105 153C140 161 164 152 182 126C182 112 168 91 155 97C147 101 155 112 161 109C167 105 172 111 169 119C157 141 133 130 126 103C107 110 96 127 105 153Z" fill="${paper}"/><path d="M111 146C89 128 89 101 98 88C112 103 126 121 139 136Z" fill="${gold}"/><path d="M112 147 75 178 124 156 99 185 137 157" fill="${paper}"/><path d="m181 126 16-4-13 10" fill="${gold}"/><circle cx="161" cy="104" r="1.5" fill="${blue}"/><path d="M150 234V255M143 258H157" stroke="${gold}" stroke-width="5" stroke-linecap="round"/></g>`;
  } else if (motif === 'mountain') {
    art = `<g class="art-back"><circle cx="208" cy="78" r="28" fill="${gold}" opacity=".75"/><path d="M21 177 81 70 133 153 167 99 235 181 280 139V264H21Z" fill="${blue}" opacity=".8"/><path d="M81 70 61 132 82 119 101 145ZM167 99 149 141 166 134 184 153Z" fill="${paper}" opacity=".6"/></g><g class="art-mid"><path d="M-5 216Q30 163 65 180L121 119L178 208L229 151L301 218V302H0Z" fill="${green}"/><path d="M121 119 100 169 123 161 146 187M229 151 210 184 230 178 247 194" fill="none" stroke="${paper}" stroke-width="1.8" opacity=".65"/><path d="M18 252Q93 223 151 244T289 238" fill="none" stroke="${gold}" stroke-width="2"/></g><g class="art-front"><path d="M44 208H113V214H44Z" fill="${red}"/><path d="M37 206Q67 194 78 177Q89 195 120 206Z" fill="${blue}"/><path d="M48 206Q78 199 108 206" stroke="${gold}" fill="none"/><path d="M54 213V246M102 213V240M78 213V244" stroke="${red}" stroke-width="6"/><path d="M40 250Q147 217 270 255V300H40Z" fill="${blue}"/><path d="M150 245Q195 256 259 257M157 258Q207 268 251 268" stroke="${paper}" stroke-width="1.2" opacity=".5" fill="none"/></g><path d="M67 88q8-10 16 0q8-10 16 0M175 53q6-7 12 0q6-7 12 0" fill="none" stroke="${blue}" stroke-width="2"/>`;
  } else if (motif === 'lantern') {
    art = `<g class="art-back"><circle cx="147" cy="138" r="91" fill="${gold}" opacity=".1"/>${branch(235,168,1,-1)}<path d="M38 197Q60 174 82 197Q107 173 130 197M189 84Q209 64 232 84Q249 67 265 84" stroke="${green}" opacity=".5" stroke-width="2" fill="none"/></g><g class="art-mid"><path d="M150 10V65" stroke="${gold}" stroke-width="3"/><path d="M123 65H177V76H123Z" fill="${blue}"/><path d="M119 77C66 101 66 170 120 193H180C234 170 234 101 181 77Z" fill="${red}"/><path d="M124 78C99 113 99 160 123 191M176 78C201 113 201 160 177 191" stroke="${gold}" stroke-width="2" fill="none"/><path d="M150 78V190" stroke="${gold}" opacity=".5" stroke-width="1"/>${flower(150,135,41,paper,8)}<path d="M122 192H178V204H122Z" fill="${blue}"/></g><g class="art-front"><path d="M150 205V226" stroke="${gold}" stroke-width="3"/><circle cx="150" cy="224" r="6" fill="${gold}"/><path d="M145 229 137 264H163L155 229Z" fill="${red}"/><path d="M144 238 142 260M150 234V263M156 238 158 260" fill="none" stroke="${gold}" stroke-width="1"/><path d="M57 234Q78 213 98 234Q119 215 139 234" stroke="${gold}" stroke-width="1.5" fill="none"/></g>`;
  } else { art = flower(150,150,90,red); }
  return `<svg class="portal-illustration" viewBox="0 0 300 300" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><pattern id="${id}-grain" width="9" height="11" patternUnits="userSpaceOnUse"><path d="m1 2 1.5.5m4 5 1-.5" stroke="${blue}" stroke-width=".5" opacity=".12"/></pattern></defs><circle cx="150" cy="150" r="126" fill="none" stroke="${gold}" stroke-width=".8" opacity=".3"/>${art}<path d="M0 0h300v300H0z" fill="url(#${id}-grain)" pointer-events="none"/></svg>`;
}
